function teamsPage(){const select=(id,items)=>'<select class="field" id="'+id+'"><option value="">Choisir…</option>'+items.map(([key,label])=>'<option value="'+e(key)+'">'+e(label)+'</option>').join('')+'</select>';return heading(manager()?'Gestion des équipes':'Mon équipe','home')+card('<b>Équipes</b>'+state.teamList.map(t=>'<div class="hoursitem">'+e(t.name)+' · Chef '+e(t.lead_user_id.slice(0,8))+'</div>').join(''))+(manager()?card('<h3>Créer une équipe</h3>'+formfield('Nom de l’équipe','teamName')+select('teamLead',state.members.filter(m=>m.role==='lead').map(m=>[m.user_id,m.user_id.slice(0,8)]))+button('Créer','createTeam','gold'))+card('<h3>Ajouter un employé à une équipe</h3>'+select('selectedTeam',state.teamList.map(t=>[t.id,t.name]))+select('teamWorker',state.members.filter(m=>['employee','lead'].includes(m.role)).map(m=>[m.user_id,m.user_id.slice(0,8)]))+button('Ajouter à l’équipe','addTeamWorker','gold'))+card('<h3>Affecter une équipe au chantier</h3>'+select('jobTeam',state.teamList.map(t=>[t.id,t.name]))+jobSelect('teamJob')+button('Affecter','assignTeamJob','gold')):'')}
async function saveTeam(action){if(!manager())return;try{let r;if(action==='createTeam'){if(!$val('teamName')||!$val('teamLead'))throw Error('Nom et chef requis');r=await sb.rpc('create_team',{p_company:company(),p_name:$val('teamName'),p_lead:$val('teamLead')})}else if(action==='addTeamWorker'){if(!$val('selectedTeam')||!$val('teamWorker'))throw Error('Équipe et employé requis');r=await sb.rpc('add_team_employee',{p_team:$val('selectedTeam'),p_employee:$val('teamWorker')})}else{if(!$val('jobTeam')||!$val('teamJob'))throw Error('Équipe et chantier requis');r=await sb.from('team_jobs').insert({company_id:company(),team_id:$val('jobTeam'),job_id:$val('teamJob')})}if(r.error)throw r.error;await reload({quiet:true});toast('Équipe enregistrée')}catch(err){error(err)}}
function approvalsPage(){
 if(!manager())return heading('Accès réservé','more');
 const choices=(action,id)=>button('Approuver',action,'gold',`data-id="${e(id)}" data-approve="true"`)+button('Refuser',action,'',`data-id="${e(id)}" data-approve="false"`);
 return heading('Approbations et paie','more')+geofenceReviewCard()+card('<b>Corrections en attente</b>'+state.corrections.filter(c=>c.status==='pending').map(c=>'<div class="group"><b>'+e(c.reason)+'</b><div class="small">'+e(c.requested_start?when(c.requested_start):'Entrée inchangée')+' → '+e(c.requested_end?when(c.requested_end):'Sortie inchangée')+'</div>'+choices('reviewCorrection',c.id)+'</div>').join(''))+
 card('<b>Congés en attente</b>'+state.leaves.filter(l=>l.status==='pending').map(l=>'<div class="group">'+e(l.begins_on)+' → '+e(l.ends_on)+' · '+e(l.leave_type)+choices('reviewLeave',l.id)+'</div>').join(''))+
 card('<b>Suivi des commandes</b>'+state.orders.map(o=>'<div class="group">'+e(o.note)+' · '+e(stateText(o.status))+({requested:button('Approuver','advanceOrder','gold',`data-id="${e(o.id)}" data-status="approved"`)+button('Refuser','advanceOrder','',`data-id="${e(o.id)}" data-status="rejected"`),approved:button('Marquer commandé','advanceOrder','',`data-id="${e(o.id)}" data-status="ordered"`),ordered:button('Marquer livré','advanceOrder','',`data-id="${e(o.id)}" data-status="delivered"`)}[o.status]||'')+'</div>').join(''))+
 card('<b>Fermeture hebdomadaire</b><p class="small muted">Une semaine fermée bloque les corrections jusqu’à une réouverture motivée. Fuseau : Québec.</p>'+formfield('Lundi de la semaine','payrollWeek','','date')+button('Fermer la semaine','closeWeek','gold')+button('Rouvrir','reopenWeek')+state.weeks.map(w=>'<div class="hoursitem">'+e(w.week_start)+' · '+(w.reopened_at?'Rouverte':'Fermée')+'</div>').join('')+button('Export CSV de la compagnie','exportHours','full'))+
 card('<b>Historique des décisions</b>'+state.audit.map(a=>'<div class="hoursitem"><div class="grow">'+e(a.action)+'<small>'+e(a.reason)+' · '+when(a.created_at)+'</small></div></div>').join(''));
}
async function reviewRecord(rpc,id,approve){const note=prompt('Motif de la décision (minimum 3 caractères)');if(!note||note.trim().length<3)return;try{const r=await sb.rpc(rpc,{p_request:id,p_approve:approve,p_note:note});if(r.error)throw r.error;await reload({quiet:true});toast('Décision enregistrée et historisée')}catch(err){error(err)}}
async function advanceOrder(id,status){const note=prompt('Commentaire de suivi (minimum 3 caractères)');if(!note||note.trim().length<3)return;try{const r=await sb.rpc('advance_material_order',{p_order:id,p_status:status,p_note:note});if(r.error)throw r.error;await reload({quiet:true});toast('Commande mise à jour')}catch(err){error(err)}}
async function setWeek(close){const week=$val('payrollWeek');if(!week)return toast('Choisis le lundi de la semaine.');const reason=prompt('Motif de '+(close?'fermeture':'réouverture'));if(!reason||reason.trim().length<3)return;try{const r=await sb.rpc('set_payroll_week',{p_company:company(),p_week:week,p_close:close,p_reason:reason});if(r.error)throw r.error;await reload({quiet:true});toast(close?'Semaine fermée':'Semaine rouverte')}catch(err){error(err)}}
function csvCell(v){let t=String(v??'');if(/^[=+@\t\r-]/.test(t))t="'"+t;return '"'+t.replace(/"/g,'""')+'"'}
async function exportHours(){try{
 let rows=[],offset=0;while(true){let q=sb.from('punch_segments').select('id,session_id,job_id,started_at,ended_at,punch_sessions!inner(user_id,worker_id)').eq('company_id',company()).order('id').range(offset,offset+499);if(!manager()||state.section==='hours')q=q.eq('punch_sessions.user_id',state.user.id);const r=await q;if(r.error)throw r.error;rows.push(...(r.data||[]));if(r.data.length<500)break;offset+=500;}
 let breaks=[],breakOffset=0;while(true){const b=await sb.from('punch_breaks').select('session_id,started_at,ended_at,is_paid').eq('company_id',company()).order('id').range(breakOffset,breakOffset+499);if(b.error)throw b.error;breaks.push(...b.data);if(b.data.length<500)break;breakOffset+=500;}
 const paused=r=>breaks.filter(b=>b.session_id===r.session_id&&!b.is_paid).reduce((sum,b)=>sum+Math.max(0,Math.min(Date.parse(b.ended_at||r.ended_at),Date.parse(r.ended_at))-Math.max(Date.parse(b.started_at),Date.parse(r.started_at))),0);
 const data=[['Segment',isEssential()?'Matricule':'Employé',isEssential()?'Lieu':'Job','Entrée ISO','Sortie ISO','Heures brutes','Pauses non payées (h)','Heures nettes','Anomalie'],...rows.map(r=>[r.id,(isEssential()?(essentialUI.planning.state.roster.find(w=>w.id===r.punch_sessions.worker_id)?.employee_number||r.punch_sessions.worker_id||r.punch_sessions.user_id):(r.punch_sessions.user_id||r.punch_sessions.worker_id)),isEssential()?(essentialUI.planning.state.locations.find(l=>l.punch_job_id===r.job_id)?.name||'Établissement'):getJob(r.job_id)?.number||r.job_id,r.started_at,r.ended_at||'',r.ended_at?((Date.parse(r.ended_at)-Date.parse(r.started_at))/3600000).toFixed(4):'',r.ended_at?(paused(r)/3600000).toFixed(4):'',r.ended_at?((Date.parse(r.ended_at)-Date.parse(r.started_at)-paused(r))/3600000).toFixed(4):'',!r.ended_at?'SORTIE MANQUANTE':Date.parse(r.ended_at)-Date.parse(r.started_at)>16*3600000?'PLUS DE 16H':''])];
 const blob=new Blob(['\uFEFF'+data.map(r=>r.map(csvCell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='PUNCH-heures-'+new Date().toISOString().slice(0,10)+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);
}catch(err){error(err)}}


function schedulePage(){if(isEssential())return essentialSchedule();return heading('Horaire et affectations','more')+(manager()?card('<b>Planifier un quart</b><div class="group"><label>Employé</label><select id="shiftUser" class="field">'+state.members.map(m=>'<option value="'+e(m.user_id)+'">'+e(m.user_id.slice(0,8))+' · '+e(labelRole(m.role))+'</option>').join('')+'</select></div>'+jobSelect('shiftJob')+formfield('Début (heure de cet appareil)','shiftStart','','datetime-local')+formfield('Fin (heure de cet appareil)','shiftEnd','','datetime-local')+formfield('Note','shiftNote')+button('Affecter au chantier','scheduleShift','gold full')):'')+card('<b>Quarts planifiés</b>'+state.shifts.map(x=>'<div class="group"><b>#'+e(getJob(x.job_id)?.number||'—')+' · '+e(x.user_id.slice(0,8))+'</b><p>'+when(x.starts_at)+' → '+when(x.ends_at)+'</p><p>'+e(x.note)+'</p>'+(manager()?button('Annuler le quart','cancelShift','',`data-id="${e(x.id)}"`):'')+'</div>').join(''));}
function jobSelect(id){if(isEssential())return '<input type="hidden" id="'+id+'" value="'+e(essentialPunchJob()||state.selected)+'" />';return '<div class="group"><label>Chantier</label><select id="'+id+'" class="field">'+state.jobs.map(j=>'<option value="'+e(j.id)+'">#'+e(j.number)+' — '+e(j.name)+'</option>').join('')+'</select></div>'}
async function scheduleShift(){try{const start=$val('shiftStart'),end=$val('shiftEnd');if(!start||!end)return toast('Début et fin requis.');const r=await sb.rpc('schedule_shift',{p_company:company(),p_user:$val('shiftUser'),p_job:$val('shiftJob'),p_start:new Date(start).toISOString(),p_end:new Date(end).toISOString(),p_note:$val('shiftNote')});if(r.error)throw r.error;await reload({quiet:true});toast('Quart planifié')}catch(err){error(err)}}
async function cancelShift(id){const reason=prompt('Motif d’annulation');if(!reason)return;try{const r=await sb.rpc('cancel_shift',{p_shift:id,p_reason:reason});if(r.error)throw r.error;await reload({quiet:true})}catch(err){error(err)}}
function invitationPage(){return heading('Invitations sécurisées','more')+(manager()?card('<p>Un abonnement actif et une place disponible sont obligatoires. Le destinataire doit confirmer son courriel.</p>'+formfield('Courriel du membre','inviteEmail','','email')+'<div class="group"><label>Rôle attribué</label><select id="inviteRole" class="field"><option value="employee">Employé</option><option value="lead">Chef d’équipe</option><option value="admin">Admin</option></select></div>'+button('Créer le lien d’invitation','createInvitation','gold full')+'<div id="inviteResult"></div>'):'')+card(formfield('Code d’invitation','inviteToken')+button('Rejoindre la compagnie invitante','acceptInvitation','full'));}
async function createInvitation(){try{const r=await sb.rpc('create_company_invitation',{p_company:company(),p_email:$val('inviteEmail'),p_role:$val('inviteRole'),p_hours:72});if(r.error)throw r.error;const url=OAUTH_REDIRECT+'?invite='+encodeURIComponent(r.data.token);$('inviteResult').innerHTML='<p>Valide 72 heures. Partage ce lien avec le destinataire :</p><textarea class="field" readonly>'+e(url)+'</textarea><p class="small">Le lien contient un code à usage unique. Copie-le maintenant.</p>'}catch(err){error(err)}}
async function acceptInvitation(){try{const token=$val('inviteToken');if(!token)return toast('Code d’invitation requis');const r=await sb.rpc('accept_company_invitation',{p_token:token});if(r.error)throw r.error;sessionStorage.removeItem('punch-invite');await initialize();toast('Compagnie rejointe avec le rôle attribué')}catch(err){error(err)}}
function documentPage(){return heading('Plans et documents','more')+(manager()?card('<b>Ajouter une révision PDF privée</b>'+jobSelect('documentJob')+formfield('Titre','documentTitle')+formfield('Version','documentVersion','1','number','min="1"')+'<div class="group"><label>Fichier PDF (25 Mo maximum)</label><input class="field" id="documentFile" type="file" accept="application/pdf" /></div><label><input id="documentAck" type="checkbox" checked /> Confirmation de lecture requise</label>'+button('Publier le PDF','uploadDocument','gold full')):'')+state.documents.map(d=>card('<b>'+e(d.name)+' · v'+d.version+'</b><p class="small">#'+e(getJob(d.job_id)?.number||'—')+'</p>'+button('Ouvrir le PDF privé','openDocument','',`data-id="${e(d.id)}"`)+(d.requires_ack?(state.acks.some(a=>a.document_id===d.id)?'<p>✓ Lecture confirmée</p>':button('Confirmer avoir lu cette version','ackDocument','gold',`data-id="${e(d.id)}"`)):'') )).join('');}
async function uploadDocument(){try{const file=$('documentFile')?.files?.[0],job=$val('documentJob'),title=$val('documentTitle'),version=Number($val('documentVersion'));if(!file||file.size>26214400||!title||!Number.isInteger(version)||version<1)return toast('PDF, titre et version valides requis.');const header=await file.slice(0,5).text();if(header!=='%PDF-')return toast('Ce fichier n’est pas un PDF.');const path=company()+'/'+job+'/'+crypto.randomUUID()+'.pdf';const upload=await sb.storage.from('job-documents').upload(path,file,{contentType:'application/pdf',upsert:false});if(upload.error)throw upload.error;const r=await sb.from('job_documents').insert({company_id:company(),job_id:job,name:title,kind:'plan',storage_path:path,version,requires_ack:$('documentAck').checked,created_by:state.user.id});if(r.error)throw r.error;await reload({quiet:true});toast('Version PDF publiée dans le stockage privé')}catch(err){error(err)}}
async function openDocument(id){const d=state.documents.find(d=>d.id===id);if(!d)return;const popup=window.open('about:blank','_blank');try{const r=await sb.storage.from('job-documents').createSignedUrl(d.storage_path,60);if(r.error)throw r.error;if(popup){popup.opener=null;popup.location=r.data.signedUrl}else toast('Autorise les fenêtres pour ouvrir le PDF')}catch(err){popup?.close();error(err)}}
async function ackDocument(id){if(!confirm('Confirmer avoir pris connaissance de cette version ?'))return;try{const r=await sb.from('document_acknowledgements').insert({document_id:id,user_id:state.user.id});if(r.error&&r.error.code!=='23505')throw r.error;await reload({quiet:true})}catch(err){error(err)}}
const workerInvitation=new URLSearchParams(location.search).get('workerInvite');if(workerInvitation&&/^[0-9a-f]{64}$/i.test(workerInvitation)){sessionStorage.setItem('punch-worker-invite',workerInvitation);state.authMode='login';state.creationEdition='essential';history.replaceState(null,'',location.pathname);}
const receivedInvitation=new URLSearchParams(location.search).get('invite');if(receivedInvitation){sessionStorage.setItem('punch-invite',receivedInvitation);history.replaceState(null,'',location.pathname);}


async function freshPunchFix(){return new Promise(resolve=>{if(!navigator.geolocation)return resolve(null);navigator.geolocation.getCurrentPosition(p=>resolve({latitude:p.coords.latitude,longitude:p.coords.longitude,accuracy:p.coords.accuracy}),()=>resolve(null),{enableHighAccuracy:true,timeout:12000,maximumAge:0})})}
const journalInstances=new Map();
function punchJournal(){const key=state.user.id+':'+company();if(!journalInstances.has(key))journalInstances.set(key,new PunchJournal({company:company(),user:state.user.id,withLock:fn=>navigator.locks?navigator.locks.request('punch-journal:'+key,fn):fn(),uuid:()=>crypto.randomUUID(),storage:{get:async key=>localStorage.getItem(key),set:async(key,value)=>localStorage.setItem(key,value)},send:async event=>{if(!navigator.onLine)throw Error('Réseau indisponible');const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),10000);try{const request=event.action==='break_start'&&event.paid?sb.rpc('sync_paid_break_start',{p_event:event.id,p_company:event.company,p_occurred_at:event.occurredAt,p_offline:event.offline,p_previous:event.previous}):event.action.startsWith('break_')?sb.rpc('sync_break_event',{p_event:event.id,p_company:event.company,p_action:event.action,p_occurred_at:event.occurredAt,p_offline:event.offline,p_previous:event.previous}):sb.rpc('sync_punch_event',{p_event:event.id,p_company:event.company,p_action:event.action,p_occurred_at:event.occurredAt,p_offline:event.offline,p_job:event.job,p_latitude:event.fix?.latitude??null,p_longitude:event.fix?.longitude??null,p_accuracy:event.fix?.accuracy??null,p_previous:event.previous});const r=await request.abortSignal(controller.signal);if(r.error)throw r.error;return r.data;}finally{clearTimeout(timer)}}}));return journalInstances.get(key);}
function saveOfflineSnapshot(){if(!member())return;localStorage.setItem('punch-snapshot:'+state.user.id+':'+company(),JSON.stringify({company:company(),jobs:state.jobs,assignments:state.assignments,shifts:state.shifts,serverPunch:state.serverPunch,selected:state.selected}));}
function restoreOfflineSnapshot(){if(!state.user||!company())return;const data=JSON.parse(localStorage.getItem('punch-snapshot:'+state.user.id+':'+company())||'null');if(data?.company===company()){state.jobs=data.jobs||[];state.assignments=data.assignments||[];state.shifts=data.shifts||[];state.serverPunch=data.serverPunch||{sessions:[],segments:[],breaks:[]};state.sessions=state.serverPunch.sessions||[];state.segments=state.serverPunch.segments||[];state.breaks=state.serverPunch.breaks||[];state.selected=data.selected;}}
async function locatedPunch(action,job,paid=false){const at=new Date().toISOString(),fix=action.startsWith('break_')?null:await freshPunchFix(),journal=punchJournal();const event=await journal.append(action,job,fix,at,paid);const sync=await journal.flush(),saved=sync.events.find(e=>e.id===event.id);if(saved?.status==='conflict')toast('Événement conservé et conflit transmis à l’administration');return {...saved?.result,review_status:saved?.status==='pending'?'local':saved?.result?.review_status};}
window.addEventListener('online',()=>{if(member())reload({quiet:true})});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&member())reload({quiet:true})});
setInterval(()=>{if(member()&&!state.busy)reload({quiet:true})},30000);

const locationLabel={inside:'Dans le rayon',outside:'Hors rayon',missing:'GPS absent',inaccurate:'GPS imprécis',job_unconfigured:'Coordonnées chantier manquantes'};
function geofenceReviewCard(){return breakApprovals()+card('<b>Conflits de synchronisation conservés</b>'+state.receipts.filter(r=>r.result?.sync_status==='conflict').map(r=>'<div class="group">'+e(r.user_id.slice(0,8))+' · '+e(r.action)+' · '+when(r.occurred_at)+'<p>'+e(r.result.message)+'</p></div>').join(''))+card('<b>Punchs GPS en attente</b>'+state.locationChecks.filter(c=>c.review_status==='pending').map(c=>'<div class="group"><b>#'+e(getJob(c.job_id)?.number||'—')+' · '+e(locationLabel[c.location_status])+(c.offline?' · HORS LIGNE':'')+'</b><p class="small">'+e(c.user_id.slice(0,8))+' · '+when(c.recorded_at)+' · '+e(c.action)+'</p><p class="small">Distance : '+(c.distance_m==null?'inconnue':Math.round(c.distance_m)+' m')+' / maximum '+c.radius_m+' m · précision '+(c.accuracy_m==null?'inconnue':Math.round(c.accuracy_m)+' m')+'</p>'+button('Accepter le punch','reviewLocation','gold',`data-id="${e(c.id)}"`)+button('Corriger les heures','correctLocation','',`data-id="${e(c.id)}"`)+'</div>').join(''));}
function geofencePage(){if(!manager())return heading('Accès réservé','more');return heading(isEssential()?'Périmètre de l’établissement':'Rayon de punch par job','more')+card('<p>Le rayon est mesuré depuis les coordonnées de l’établissement. Un punch hors rayon est conservé et attend une validation. Le GPS absent ou imprécis nécessite aussi une validation.</p>')+state.jobs.map(j=>card('<b>'+e(isEssential()?'Mon établissement':'#'+j.number+' — '+j.name)+'</b>'+formfield('Latitude','geoLat-'+j.id,j.latitude??'','number','step="any"')+formfield('Longitude','geoLon-'+j.id,j.longitude??'','number','step="any"')+formfield('Rayon maximal (10 à 10 000 mètres)','geoRadius-'+j.id,j.punch_radius_m||200,'number','min="10" max="10000"')+button('Enregistrer le périmètre','saveGeofence','gold',`data-id="${e(j.id)}"`))).join('')+geofenceReviewCard();}
async function saveGeofence(id){try{const lat=$val('geoLat-'+id),lon=$val('geoLon-'+id),radius=Number($val('geoRadius-'+id));if(!lat||!lon||!Number.isFinite(Number(lat))||!Number.isFinite(Number(lon))||!Number.isInteger(radius))return toast('Coordonnées et rayon valides requis');const r=await sb.from('jobs').update({latitude:Number(lat),longitude:Number(lon),punch_radius_m:radius}).eq('id',id).eq('company_id',company()).select('id').single();if(r.error)throw r.error;await reload({quiet:true});toast('Rayon du chantier enregistré')}catch(err){error(err)}}
async function reviewLocation(id,correct){const note=prompt('Motif de validation ou de correction (minimum 3 caractères)');if(!note||note.trim().length<3)return;let start=null,end=null;if(correct){const a=prompt('Nouvelle entrée ISO avec fuseau (vide = inchangée)');if(a===null)return;const b=prompt('Nouvelle sortie ISO avec fuseau (vide = inchangée)');if(b===null)return;try{start=a?new Date(a).toISOString():null;end=b?new Date(b).toISOString():null}catch{return toast('Dates invalides')}if(!start&&!end)return toast('Indique au moins une heure à corriger.');}try{const r=await sb.rpc('review_punch_location',{p_check:id,p_note:note,p_start:start,p_end:end});if(r.error)throw r.error;await reload({quiet:true});toast(correct?'Heures corrigées et validation historisée':'Punch accepté et historisé')}catch(err){error(err)}}
function notificationsPage(){return heading('Notifications','more')+(isEssential()?essentialUI.notificationPreferences.render():'')+state.notifications.map(n=>card('<b>'+e(n.title)+'</b><p>'+e(n.body)+'</p><p class="small">'+when(n.created_at)+'</p>'+(!n.read_at?button('Marquer comme lue','readNotification','',`data-id="${e(n.id)}"`):'<p class="small">Lue</p>')+(n.location_check_id&&manager()?button('Voir les punchs à valider','subpage','gold','data-id="geofence"'):'') )).join('');}
async function readNotification(id){try{const r=await sb.from('app_notifications').update({read_at:new Date().toISOString()}).eq('id',id).eq('recipient_id',state.user.id);if(r.error)throw r.error;await reload({quiet:true})}catch(err){error(err)}}


function isEssential(){return state.account?.companies?.product_edition==='essential'||(!member()&&state.creationEdition==='essential')}
function siteLabel(id){return isEssential()?'Établissement':'#'+(getJob(id)?.number||'—')}
function planCards(){return '<div class="plan-cards"><button type="button" class="plan-card '+(state.creationEdition==='essential'?'chosen':'')+'" data-action="chooseEdition" data-id="essential"><span class="plan-kicker">BUREAUX · MANUFACTURES</span><strong>PUNCH Essentiel</strong><span>Punch, pauses, heures et congés. Simplement.</span><b>Trois forfaits disponibles</b><small>Consultez les tarifs ci-dessous</small></button><button type="button" class="plan-card '+(state.creationEdition==='construction'?'chosen':'')+'" data-action="chooseEdition" data-id="construction"><span class="plan-kicker">CHANTIERS · ÉQUIPES MOBILES</span><strong>PUNCH Construction</strong><span>Jobs, matériel, plans et équipes.</span><b>49 $ CA / mois</b><small>5 personnes incluses · +7 $ / personne</small></button></div>'}
function essentialToday(){const d=new Date(state.time);return totals(new Date(d.getFullYear(),d.getMonth(),d.getDate()).getTime())}
function essentialBase(){const tabs=[['home','◉',manager()?tr('management'):tr('punch')],['hours','◷',tr('hours')],['schedule','▦',tr('schedule')],['more','☷',tr('more')]];return '<div class="wrap"><aside class="pitch essential-pitch"><div class="kicker">PUNCH ESSENTIEL</div><h1>Du temps.<br>De la <b>simplicité.</b></h1><p>Le pointage qui laisse respirer votre journée.</p><div class="zen-orbit">◌</div><p class="small">Bureaux · ateliers · manufactures</p></aside><div class="phone"><header class="header"><div class="essential-brand"><span class="brand-mark">p</span><div>PUNCH <span>Essentiel</span></div></div><button class="iconbutton" data-action="subpage" data-id="notifications" aria-label="Notifications">♧ '+state.notifications.filter(n=>!n.read_at).length+'</button></header><main id="main">'+(state.fieldMode?button('← Direction','navigate','full','data-id="management"'):'')+(state.recovery?authHTML():member()?essentialPage():authHTML())+'</main><div class="banner">'+(member()?(state.localPending?'◌ '+state.localPending+' événement(s) conservé(s) sur cet appareil':'Données de test · validation terrain à effectuer'):'PUNCH · choisir la simplicité')+'</div>'+(member()?'<nav class="nav">'+tabs.map(t=>'<button class="'+(state.section===t[0]?'active':'')+'" data-action="navigate" data-id="'+t[0]+'"><i>'+t[1]+'</i><span>'+t[2]+'</span></button>').join('')+'</nav>':'')+'<div class="toast" id="toast" style="display:none"></div></div></div>'}
function essentialNavigationState(){
 if(!isEssential()||!state.user?.id||!state.account?.company_id)return null;
 const worker=essentialUI.state.worker,planning=essentialUI.planning.state;
 if(!worker?.id||planning.company!==company())return null;
 const visit=personalUpcomingClientVisit(planning.assignedSites,worker.id,Date.now());
 const fixed=planning.locations.find(l=>l.id===worker.location_id);
 const destination=navigationDestination({visit,usualAddress:fixed?.address||'',
  usualName:fixed?.name||'Établissement habituel',incomplete:planning.assignedSitesUnavailable});
 if(!destination)return null;
 const platform=navigationPlatform('web',navigator.userAgent);
 const key=navigationPreferenceKey(state.user.id,company());
 const saved=chooseNavigationPreference(localStorage.getItem(key),platform);
 return {destination,platform,key,saved};
}
function essentialNavigationSettingsCard(){
 if(!isEssential()||!state.user?.id||!company())return '';
 const platform=navigationPlatform('web',navigator.userAgent);
 const key=navigationPreferenceKey(state.user.id,company());
 let stored=null;
 try{stored=localStorage.getItem(key)}catch{return card('<b>Navigation</b><p role="alert">Préférences indisponibles sur ce navigateur. Vous pouvez toujours choisir l’application depuis l’Accueil Punch.</p>')}
 const current=chooseNavigationPreference(stored,platform);
 const providers=navigationProviders(platform);
 return card('<section aria-label="Réglages de navigation"><h3>Navigation · application préférée</h3>'+
  '<p class="small muted">Votre choix s’applique seulement à ce compte et à cette compagnie, sur cet appareil. Pas besoin d’un horaire ni d’une destination pour régler l’application. Aucune adresse, GPS ou trajet n’est mémorisé.</p>'+
  '<div role="group" aria-label="Application de navigation">'+providers.map(provider=>
   '<button type="button" class="listitem" data-action="navPrefSet" data-id="'+e(provider.id)+'" aria-pressed="'+(current===provider.id?'true':'false')+'"><span class="grow">'+e(provider.label)+'</span><span>'+(current===provider.id?'✓':'Choisir')+'</span></button>'
  ).join('')+'</div>'+
  '<p class="small muted">La préférence actuelle : '+e(providers.find(p=>p.id===current)?.label||'Demander à chaque utilisation')+'.</p>'+
  (current?button('Effacer ma préférence','navPrefClear','full'):'')+
  '<p class="small muted">Pour démarrer un trajet, utilisez « Itinéraire » dans Accueil Punch. Les applications installées ne sont pas détectables de façon fiable depuis tous les navigateurs.</p></section>');
}
function essentialNavigationCard(){
 const stateNav=essentialNavigationState();
 if(!stateNav)return '';
 const {destination,platform,saved}=stateNav;
 const choices=navigationProviders(platform);
 const preferred=choices.find(p=>p.id===saved);
 const direct=preferred?'<p><a class="ess-btn" href="'+e(navigationUrl(saved,destination.address,platform))+'" target="_blank" rel="noopener noreferrer">Itinéraire avec '+e(preferred.label)+' ↗</a></p>':'';
 return '<section class="zen-company" aria-label="Navigation vers votre travail"><div>'+
  '<strong>Itinéraire · '+e(destination.title)+'</strong><small>'+e(destination.address)+'</small>'+
  '<small>'+(destination.kind==='client'?'Intervention du calendrier':'Lieu de travail habituel · aucun horaire requis')+'</small>'+
  direct+
  '<details '+(!preferred?'open':'')+'><summary>'+(preferred?"Changer d'application de navigation":"Choisir l'application de navigation")+'</summary>'+
  '<p class="ess-fine">Le lien ouvre l’application si disponible ou son site Web. Aucun pointage ni GPS continu n’est déclenché.</p>'+
  choices.map(choice=>'<div class="plan-actions"><a href="'+e(navigationUrl(choice.id,destination.address,platform))+'" target="_blank" rel="noopener noreferrer">'+e(choice.label)+' · juste cette fois ↗</a>'+
   '<button type="button" class="ess-btn" data-action="navRemember" data-id="'+e(choice.id)+'">Toujours '+e(choice.label)+'</button></div>').join('')+
  (preferred?'<button type="button" class="ess-btn" data-action="navForget">Effacer ma préférence</button>':'')+
  '</details></div></section>';
}
