async function lookupAccount(){
 state.account=null;companyContext.list=[];companyContext.choosing=false;
 if(!state.user)return;
 const q=await sb.from('company_members').select('user_id,company_id,role,status,companies(name,billing_status,product_edition,default_punch_job_id)')
  .eq('user_id',state.user.id).eq('status','active').order('company_id').limit(100);
 if(q.error)throw Error('Vérification des entreprises impossible. Reconnectez-vous pour vérifier vos accès.');
 const verified=listVerifiedWorkspaces(q.data||[],state.user);companyContext.list=verified;
 const requested=localStorage.getItem('punch-last-company:'+state.user.id);
 const choice=chooseVerifiedWorkspace(verified,requested);
 if(!choice){companyContext.choosing=verified.length>1;return;}
 setVerifiedAccount(choice);
}
function setVerifiedAccount(choice){
 if(!state.user||choice.userId!==state.user.id)throw Error('Compte incohérent.');
 state.account={company_id:choice.companyId,role:choice.role,companies:{name:choice.companyName,
  billing_status:choice.billingStatus,product_edition:choice.edition,default_punch_job_id:choice.defaultJobId}};
 localStorage.setItem('punch-last-company:'+state.user.id,choice.companyId);
 // Do not persist role snapshots across unverified login. Offline identity is separate.
 companyContext.choosing=false;
 localStorage.setItem('punch-account:'+state.user.id+':'+choice.companyId,JSON.stringify(state.account));
}
